    public var columns: (simd_double3, simd_double3, simd_double3, simd_double3)

    @inlinable public init() { columns = (.zero, .zero, .zero, .zero) }

    @inlinable public init(columns: (simd_double3, simd_double3, simd_double3, simd_double3)) { self.columns = columns }
}

extension simd_double4x3 {
    /// `scalar` along the diagonal, zero elsewhere.
    @inlinable public init(_ scalar: Double) { self.init(diagonal: simd_double3(repeating: scalar)) }

    @inlinable public init(diagonal: SIMD3<Double>) {
        self.init()
        columns.0[0] = diagonal[0]
        columns.1[1] = diagonal[1]
        columns.2[2] = diagonal[2]
    }

    @inlinable public init(_ columns: [SIMD3<Double>]) {
        precondition(columns.count == 4, "Requires array of 4 vectors")
        self.init(columns: (columns[0], columns[1], columns[2], columns[3]))
    }

    @inlinable public init(rows: [SIMD4<Double>]) {
        precondition(rows.count == 3, "Requires array of 3 vectors")
        self.init(columns: (simd_double3(rows[0][0], rows[1][0], rows[2][0]), simd_double3(rows[0][1], rows[1][1], rows[2][1]), simd_double3(rows[0][2], rows[1][2], rows[2][2]), simd_double3(rows[0][3], rows[1][3], rows[2][3])))
    }

    @inlinable public init(_ col0: SIMD3<Double>, _ col1: SIMD3<Double>, _ col2: SIMD3<Double>, _ col3: SIMD3<Double>) { self.init(columns: (col0, col1, col2, col3)) }

    @inlinable public init(_ cmatrix: simd_double4x3) { self = cmatrix }

    @inlinable public var cmatrix: simd_double4x3 { self }

    @inlinable public subscript(column: Int) -> SIMD3<Double> {
        get {
            switch column {
            case 0: return columns.0
            case 1: return columns.1
            case 2: return columns.2
            case 3: return columns.3
            default: preconditionFailure("Column index out of range")
            }
        }
        set {
            switch column {
            case 0: columns.0 = newValue
            case 1: columns.1 = newValue
            case 2: columns.2 = newValue
            case 3: columns.3 = newValue
            default: preconditionFailure("Column index out of range")
            }
        }
    }

    @inlinable public subscript(column: Int, row: Int) -> Double {
        get { self[column][row] }
        set { self[column][row] = newValue }
    }

    @inlinable public var transpose: simd_double3x4 {
        simd_double3x4(columns: (simd_double4(columns.0[0], columns.1[0], columns.2[0], columns.3[0]), simd_double4(columns.0[1], columns.1[1], columns.2[1], columns.3[1]), simd_double4(columns.0[2], columns.1[2], columns.2[2], columns.3[2])))
    }
}

extension simd_double4x3: CustomDebugStringConvertible {
    @inlinable public var debugDescription: String {
        "simd_double4x3([\(arrayDescription(columns.0)), \(arrayDescription(columns.1)), \(arrayDescription(columns.2)), \(arrayDescription(columns.3))])"
    }
}

extension simd_double4x3: Equatable {
    @inlinable public static func == (lhs: simd_double4x3, rhs: simd_double4x3) -> Bool {
        lhs.columns.0 == rhs.columns.0 && lhs.columns.1 == rhs.columns.1 && lhs.columns.2 == rhs.columns.2 && lhs.columns.3 == rhs.columns.3
    }
}

extension simd_double4x3 {
    @inlinable public static func + (lhs: simd_double4x3, rhs: simd_double4x3) -> simd_double4x3 { simd_double4x3(columns: (lhs.columns.0 + rhs.columns.0, lhs.columns.1 + rhs.columns.1, lhs.columns.2 + rhs.columns.2, lhs.columns.3 + rhs.columns.3)) }
    @inlinable public static prefix func - (rhs: simd_double4x3) -> simd_double4x3 { simd_double4x3(columns: (-rhs.columns.0, -rhs.columns.1, -rhs.columns.2, -rhs.columns.3)) }
    @inlinable public static func - (lhs: simd_double4x3, rhs: simd_double4x3) -> simd_double4x3 { simd_double4x3(columns: (lhs.columns.0 - rhs.columns.0, lhs.columns.1 - rhs.columns.1, lhs.columns.2 - rhs.columns.2, lhs.columns.3 - rhs.columns.3)) }
    @inlinable public static func += (lhs: inout simd_double4x3, rhs: simd_double4x3) { lhs = lhs + rhs }
    @inlinable public static func -= (lhs: inout simd_double4x3, rhs: simd_double4x3) { lhs = lhs - rhs }
    @inlinable public static func * (lhs: Double, rhs: simd_double4x3) -> simd_double4x3 { simd_double4x3(columns: (lhs * rhs.columns.0, lhs * rhs.columns.1, lhs * rhs.columns.2, lhs * rhs.columns.3)) }
    @inlinable public static func * (lhs: simd_double4x3, rhs: Double) -> simd_double4x3 { rhs * lhs }
    @inlinable public static func *= (lhs: inout simd_double4x3, rhs: Double) { lhs = lhs * rhs }
    @inlinable public static func * (lhs: simd_double4x3, rhs: SIMD4<Double>) -> SIMD3<Double> { lhs.columns.0 * rhs[0] + lhs.columns.1 * rhs[1] + lhs.columns.2 * rhs[2] + lhs.columns.3 * rhs[3] }
    @inlinable public static func * (lhs: SIMD3<Double>, rhs: simd_double4x3) -> SIMD4<Double> {
        SIMD4(dotFloat(lhs, rhs.columns.0), dotFloat(lhs, rhs.columns.1), dotFloat(lhs, rhs.columns.2), dotFloat(lhs, rhs.columns.3))
    }
    @inlinable public static func * (lhs: simd_double4x3, rhs: simd_double2x4) -> simd_double2x3 {
        simd_double2x3(columns: (lhs * rhs.columns.0, lhs * rhs.columns.1))
    }
    @inlinable public static func * (lhs: simd_double4x3, rhs: simd_double3x4) -> simd_double3x3 {
        simd_double3x3(columns: (lhs * rhs.columns.0, lhs * rhs.columns.1, lhs * rhs.columns.2))
    }
    @inlinable public static func * (lhs: simd_double4x3, rhs: simd_double4x4) -> simd_double4x3 {
        simd_double4x3(columns: (lhs * rhs.columns.0, lhs * rhs.columns.1, lhs * rhs.columns.2, lhs * rhs.columns.3))
    }
    @inlinable public static func *= (lhs: inout simd_double4x3, rhs: simd_double4x4) { lhs = lhs * rhs }
}

/// 4 columns of 4 Doubles.
@frozen
public struct simd_double4x4: Sendable {
    public var columns: (simd_double4, simd_double4, simd_double4, simd_double4)

    @inlinable public init() { columns = (.zero, .zero, .zero, .zero) }

    @inlinable public init(columns: (simd_double4, simd_double4, simd_double4, simd_double4)) { self.columns = columns }
}

extension simd_double4x4 {
    /// `scalar` along the diagonal, zero elsewhere.
    @inlinable public init(_ scalar: Double) { self.init(diagonal: simd_double4(repeating: scalar)) }

    @inlinable public init(diagonal: SIMD4<Double>) {
        self.init()
        columns.0[0] = diagonal[0]
        columns.1[1] = diagonal[1]
        columns.2[2] = diagonal[2]
        columns.3[3] = diagonal[3]
    }

    @inlinable public init(_ columns: [SIMD4<Double>]) {
        precondition(columns.count == 4, "Requires array of 4 vectors")
        self.init(columns: (columns[0], columns[1], columns[2], columns[3]))
    }

    @inlinable public init(rows: [SIMD4<Double>]) {
        precondition(rows.count == 4, "Requires array of 4 vectors")
        self.init(columns: (simd_double4(rows[0][0], rows[1][0], rows[2][0], rows[3][0]), simd_double4(rows[0][1], rows[1][1], rows[2][1], rows[3][1]), simd_double4(rows[0][2], rows[1][2], rows[2][2], rows[3][2]), simd_double4(rows[0][3], rows[1][3], rows[2][3], rows[3][3])))
    }

    @inlinable public init(_ col0: SIMD4<Double>, _ col1: SIMD4<Double>, _ col2: SIMD4<Double>, _ col3: SIMD4<Double>) { self.init(columns: (col0, col1, col2, col3)) }

    @inlinable public init(_ cmatrix: simd_double4x4) { self = cmatrix }

    @inlinable public var cmatrix: simd_double4x4 { self }

    @inlinable public subscript(column: Int) -> SIMD4<Double> {
        get {
            switch column {
            case 0: return columns.0
            case 1: return columns.1
            case 2: return columns.2
            case 3: return columns.3
            default: preconditionFailure("Column index out of range")
            }
        }
        set {
            switch column {
            case 0: columns.0 = newValue
            case 1: columns.1 = newValue
            case 2: columns.2 = newValue
            case 3: columns.3 = newValue
            default: preconditionFailure("Column index out of range")
            }
        }
    }

    @inlinable public subscript(column: Int, row: Int) -> Double {
        get { self[column][row] }
        set { self[column][row] = newValue }
    }

    @inlinable public var transpose: simd_double4x4 {
        simd_double4x4(columns: (simd_double4(columns.0[0], columns.1[0], columns.2[0], columns.3[0]), simd_double4(columns.0[1], columns.1[1], columns.2[1], columns.3[1]), simd_double4(columns.0[2], columns.1[2], columns.2[2], columns.3[2]), simd_double4(columns.0[3], columns.1[3], columns.2[3], columns.3[3])))
    }

    @inlinable public var inverse: simd_double4x4 { simd_double4x4(columns: NucleantSIMDPortable.inverse(columns.0, columns.1, columns.2, columns.3)) }

    @inlinable public var determinant: Double { NucleantSIMDPortable.determinant(columns.0, columns.1, columns.2, columns.3) }

    /// The rotation `quaternion` makes.
    @inlinable public init(_ quaternion: simd_quatd) {
        let r = rotationColumns(quaternion.vector)
        self.init(columns: (simd_double4(r.0, 0), simd_double4(r.1, 0), simd_double4(r.2, 0), simd_double4(0, 0, 0, 1)))
    }
}

