@inlinable public func simd_matrix(_ col0: simd_float2, _ col1: simd_float2) -> simd_float2x2 { simd_float2x2(columns: (col0, col1)) }
@inlinable public func simd_matrix_from_rows(_ row0: simd_float2, _ row1: simd_float2) -> simd_float2x2 { simd_float2x2(rows: [row0, row1]) }
@inlinable public func simd_mul(_ a: Float, _ x: simd_float2x2) -> simd_float2x2 { a * x }
@inlinable public func matrix_scale(_ a: Float, _ x: simd_float2x2) -> simd_float2x2 { a * x }
@inlinable public func simd_linear_combination(_ a: Float, _ x: simd_float2x2, _ b: Float, _ y: simd_float2x2) -> simd_float2x2 { a * x + b * y }
@inlinable public func simd_add(_ x: simd_float2x2, _ y: simd_float2x2) -> simd_float2x2 { x + y }
@inlinable public func simd_sub(_ x: simd_float2x2, _ y: simd_float2x2) -> simd_float2x2 { x - y }
@inlinable public func simd_transpose(_ x: simd_float2x2) -> simd_float2x2 { x.transpose }
@inlinable public func simd_equal(_ x: simd_float2x2, _ y: simd_float2x2) -> simd_bool { x == y }
@inlinable public func simd_almost_equal_elements(_ x: simd_float2x2, _ y: simd_float2x2, _ tol: Float) -> simd_bool { all(absFloat(x.columns.0 - y.columns.0) .<= simd_float2(repeating: tol)) && all(absFloat(x.columns.1 - y.columns.1) .<= simd_float2(repeating: tol)) }
@inlinable public func simd_almost_equal_elements_relative(_ x: simd_float2x2, _ y: simd_float2x2, _ tol: Float) -> simd_bool { all(absFloat(x.columns.0 - y.columns.0) .<= tol * absFloat(x.columns.0)) && all(absFloat(x.columns.1 - y.columns.1) .<= tol * absFloat(x.columns.1)) }
