@inlinable public func simd_determinant(_ x: simd_double4x4) -> Double { x.determinant }
@inlinable public func matrix_determinant(_ x: simd_double4x4) -> Double { x.determinant }
@inlinable public func simd_trace(_ x: simd_double4x4) -> Double { x.columns.0[0] + x.columns.1[1] + x.columns.2[2] + x.columns.3[3] }

